    "statement": "No studies have evaluated the effects of releasing captive-bred bats on bat populations.",
    "citations": [
      "2039"
    ]
  },
  {
    "statement": "There is no evidence available on the long-term success rates of reintroducing captive-bred bats.",
    "citations": [
      "2039"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of educating the public to improve the perception of bats.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of educating the public to improve behaviour towards bats.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "The effectiveness of public education on bats could not be assessed.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "Any variation in the effectiveness of public education on bats between continents could not be assessed.",
    "citations": [
      "1000"
    ]
  }
]

[
  {
    "statement": "Evidence on artificial bat roost creation reports outcomes but does not provide cost-effectiveness data.",
    "citations": []
  },
  {
    "statement": "Providing bat boxes, bat grilles, or roost improvements has no captured evidence for effects on farmland wildlife.",
    "citations": [
      "95"
    ]
  },
  {
    "statement": "A before-and-after study in Spain found more bats in two artificial roosts after reducing the roosts' internal temperatures.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "In the UK, heated bat boxes were used by common pipistrelles at one of seven sites.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "Heated bat boxes in the UK were not used by maternity colonies.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "None of twelve heated boxes in churches were used by displaced Natterer’s bats.",
    "citations": [
      "2052"
    ]
  },
  {
    "statement": "A UK study found bat numbers using an artificial hibernaculum increased in each of nine years after construction of the hibernaculum.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Another UK study recorded use of an artificial cave by a small number of brown long-eared bats.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Studies in Germany and the UK recorded use of artificial hibernacula by up to four bat species.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Two replicated studies in the USA and UK found no use of provided bat houses or a purpose-built bat wall after bat exclusion.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Other studies or reviews reported bat boxes or bat lofts/barns were used at 13–74% of sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Maternity use of bat boxes or bat lofts/barns was reported at one of 19 sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Three out of five before-and-after studies reported similar or higher use of purpose-built roosts after original roosts were destroyed.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Two out of five before-and-after studies reported lower use of purpose-built roosts after original roosts were destroyed.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "A UK review found replacement roosts were four times less likely to be used than roosts retained during development.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "A USA review found that spaces created in road bridges were recolonized by bats in similar or greater numbers than original roosts at four of eight sites.",
    "citations": [
      "1967"
    ]
  }
]
